-- 006_grammar_gap_fix.sql
-- Closes the grammar gaps found in docs/cefr-alignment-audit.md:
--   - "to be" was taught too late (module 9) even though earlier modules
--     (greetings, family, food...) already rely on it productively.
--   - WH- questions, Present Simple (do/does), there is/are, imperatives,
--     and "can" for ability were tested in several lessons but never had
--     a dedicated lesson teaching the rule.
-- This file only reorders existing modules and adds ONE new module with
-- 5 new lessons. It does not touch any existing lesson or exercise rows.
-- Run AFTER 005_a1_reseed.sql.

-- ===========================================================================
-- PART 1: Fix module sequencing (move "Verbo To Be" + "Pronombres
-- Personales" earlier, insert new grammar module right after them)
-- ===========================================================================

-- Step 1: push all current A1 module order_index values negative so the
-- unique(unit_id, order_index) constraint never collides mid-reorder.
UPDATE modules SET order_index = -order_index
WHERE unit_id = '00000000-0000-0000-0001-000000000001';

-- Step 2: reassign the corrected order. "To Be" and pronouns move up
-- front; the new grammar module slots in right after them; everything
-- else keeps its relative order, shifted down to make room.
UPDATE modules SET order_index = CASE slug
  WHEN 'alfabeto-y-sonidos'        THEN 1
  WHEN 'verbo-to-be'               THEN 2
  WHEN 'pronombres-personales'     THEN 4
  WHEN 'saludos-y-presentaciones'  THEN 5
  WHEN 'numeros-y-matematicas'     THEN 6
  WHEN 'fechas-y-tiempo'           THEN 7
  WHEN 'colores-adjetivos'         THEN 8
  WHEN 'la-familia'                THEN 9
  WHEN 'comida-bebida'             THEN 10
  WHEN 'cuerpo-humano'             THEN 11
  WHEN 'articulos-sustantivos'     THEN 12
  WHEN 'lenguaje-funcional'        THEN 13
END
WHERE unit_id = '00000000-0000-0000-0001-000000000001'
AND slug IN (
  'alfabeto-y-sonidos','verbo-to-be','pronombres-personales',
  'saludos-y-presentaciones','numeros-y-matematicas','fechas-y-tiempo',
  'colores-adjetivos','la-familia','comida-bebida','cuerpo-humano',
  'articulos-sustantivos','lenguaje-funcional'
);

-- ===========================================================================
-- PART 2: New module — "Preguntas y Estructuras Básicas" (order_index 3)
-- Idempotent cleanup first, in case this file is re-run.
-- ===========================================================================

DELETE FROM exercises
WHERE lesson_id IN (
  SELECT id FROM lessons WHERE module_id = '00000001-0000-0000-0000-000000000013'
);
DELETE FROM lessons WHERE module_id = '00000001-0000-0000-0000-000000000013';
DELETE FROM modules WHERE id = '00000001-0000-0000-0000-000000000013';

INSERT INTO modules (id, unit_id, order_index, slug, title, description, is_published) VALUES
('00000001-0000-0000-0000-000000000013','00000000-0000-0000-0001-000000000001',3,'preguntas-estructuras-basicas','{"es":"Preguntas y Estructuras Básicas","en":"Basic Questions and Structures"}','{"es":"Aprende a formar preguntas con WH-words, el Presente Simple con do/does, there is/there are, los imperativos y can para expresar habilidad.","en":"Learn to form questions with WH-words, the Present Simple with do/does, there is/there are, imperatives, and can for ability."}',true);

-- ===========================================================================
-- Lesson 13.1 — Palabras Interrogativas (WH- Questions)
-- ===========================================================================

INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0013-000000000001', '00000001-0000-0000-0000-000000000013', '00000000-0000-0000-0001-000000000001', 1, 'palabras-interrogativas', '{"es": "Palabras Interrogativas", "en": "Question Words"}'::jsonb, '{"es": "Aprende a formar preguntas en inglés con what, where, when, who, why y how.", "en": "Learn to form questions in English with what, where, when, who, why, and how."}'::jsonb, 'theory_practice', 20, 15, '{"intro": "Para pedir información específica en inglés usamos palabras interrogativas (WH- words) al inicio de la pregunta. Ya viste algunas de estas palabras en frases como ''What''s your name?'' o ''Where are you from?'' — ahora vas a entender la regla completa detrás de ellas, para poder formar cualquier pregunta, no solo memorizar frases sueltas.", "sections": [{"type": "explanation", "title": "LAS PALABRAS INTERROGATIVAS PRINCIPALES", "text": "What (qué/cuál) pregunta por una cosa o información. Where (dónde) pregunta por un lugar. When (cuándo) pregunta por un momento o fecha. Who (quién) pregunta por una persona. Why (por qué) pregunta por una razón. How (cómo) pregunta por una manera, y combinado con much/many pregunta por cantidad."}, {"type": "table", "title": "PALABRAS INTERROGATIVAS Y SU USO", "headers": ["Palabra", "Pregunta por...", "Ejemplo"], "rows": [["What", "una cosa", "What is this?"], ["Where", "un lugar", "Where do you live?"], ["When", "un momento", "When is your birthday?"], ["Who", "una persona", "Who is that man?"], ["Why", "una razón", "Why are you tired?"], ["How", "una manera", "How do you spell that?"], ["How much", "cantidad (incontable)", "How much is it?"], ["How many", "cantidad (contable)", "How many books?"]]}, {"type": "explanation", "title": "EL ORDEN DE LA PREGUNTA", "text": "La estructura es: PALABRA INTERROGATIVA + VERBO + SUJETO + RESTO. Si el verbo principal es ''to be'', se invierte directamente: ''What IS your name?'' Si el verbo principal es otro (como live, work, like), necesitas el auxiliar do/does ANTES del sujeto: ''Where DO you live?'' / ''What DOES she like?''. Nunca se usan los dos juntos: NO se dice ''What is do you like?''."}, {"type": "examples", "title": "EJEMPLOS", "items": [{"label": "Con to be", "en": "Who is your teacher? — Mr. Smith is my teacher.", "es": "¿Quién es tu profesor? — El Sr. Smith es mi profesor."}, {"label": "Con do/does", "en": "Why do you study English? — Because I want to travel.", "es": "¿Por qué estudias inglés? — Porque quiero viajar."}, {"label": "How much/many", "en": "How much is the ticket? How many tickets do you need?", "es": "¿Cuánto cuesta el boleto? ¿Cuántos boletos necesitas?"}]}, {"type": "note", "variant": "tip", "text": "Truco rápido: si la pregunta tiene un verbo de acción (live, work, like, eat...) casi siempre necesitas do/does. Si la pregunta describe un estado o identidad (ser, estar), usas to be directamente."}]}'::jsonb, true);

INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0013-0001-0001-000000000001', '00000002-0000-0000-0013-000000000001', 1, 'flashcard', '{"text": "What", "subtext": "Palabra interrogativa"}'::jsonb, '{"text": "qué / cuál", "phonetic": "/wʌt/"}'::jsonb, NULL, NULL),
('00000003-0013-0001-0002-000000000001', '00000002-0000-0000-0013-000000000001', 2, 'flashcard', '{"text": "Where", "subtext": "Palabra interrogativa"}'::jsonb, '{"text": "dónde", "phonetic": "/wɛər/"}'::jsonb, NULL, NULL),
('00000003-0013-0001-0003-000000000001', '00000002-0000-0000-0013-000000000001', 3, 'flashcard', '{"text": "How much / How many", "subtext": "Preguntar cantidad"}'::jsonb, '{"text": "cuánto / cuántos", "phonetic": "/haʊ mʌtʃ, haʊ ˈmɛni/"}'::jsonb, NULL, NULL),
('00000003-0013-0001-0004-000000000001', '00000002-0000-0000-0013-000000000001', 4, 'multiple_choice', '{"text": "¿Qué palabra usas para preguntar por una persona?"}'::jsonb, '{"text": "Who"}'::jsonb, '["What", "Where", "When"]'::jsonb, '{"es": "''Who'' siempre pregunta por una persona: ''Who is she?'' (¿Quién es ella?)."}'::jsonb),
('00000003-0013-0001-0005-000000000001', '00000002-0000-0000-0013-000000000001', 5, 'multiple_choice', '{"text": "¿Cuál es la pregunta correcta para la respuesta ''I live in Madrid''?"}'::jsonb, '{"text": "Where do you live?"}'::jsonb, '["What do you live?", "Who do you live?", "Where you live?"]'::jsonb, '{"es": "''Live'' es un verbo de acción, así que la pregunta necesita el auxiliar ''do'': ''Where DO you live?''."}'::jsonb),
('00000003-0013-0001-0006-000000000001', '00000002-0000-0000-0013-000000000001', 6, 'fill_blank', '{"text": "___ is your name? (pregunta por el nombre)"}'::jsonb, '{"text": "What", "accepted": ["What"]}'::jsonb, NULL, NULL),
('00000003-0013-0001-0007-000000000001', '00000002-0000-0000-0013-000000000001', 7, 'fill_blank', '{"text": "___ are you from? (pregunta por origen)"}'::jsonb, '{"text": "Where", "accepted": ["Where"]}'::jsonb, NULL, NULL),
('00000003-0013-0001-0008-000000000001', '00000002-0000-0000-0013-000000000001', 8, 'translation', '{"text": "¿Cuántos años tienes?"}'::jsonb, '{"text": "How old are you?", "accepted": ["How old are you?"]}'::jsonb, NULL, '{"es": "''How old'' es la forma estándar de preguntar la edad — literalmente ''qué tan viejo''."}'::jsonb);

-- ===========================================================================
-- Lesson 13.2 — El Presente Simple: Forma Afirmativa
-- ===========================================================================

INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0013-000000000002', '00000001-0000-0000-0000-000000000013', '00000000-0000-0000-0001-000000000001', 2, 'presente-simple-afirmativo', '{"es": "El Presente Simple: Forma Afirmativa", "en": "Present Simple: Affirmative Form"}'::jsonb, '{"es": "Aprende a usar el Presente Simple para hablar de hábitos, rutinas y hechos generales en inglés.", "en": "Learn to use the Present Simple to talk about habits, routines, and general facts in English."}'::jsonb, 'grammar', 20, 15, '{"intro": "El Presente Simple es el tiempo verbal que usamos para hablar de hábitos, rutinas, hechos generales y cosas que siempre son verdad. Es uno de los tiempos más usados en inglés, y a diferencia de ''to be'', estos verbos cambian de forma según quién hace la acción.", "sections": [{"type": "explanation", "title": "CUÁNDO USAR EL PRESENTE SIMPLE", "text": "Usamos el Presente Simple para: hábitos y rutinas (''I work every day''), hechos generales (''Water boils at 100 degrees''), y gustos permanentes (''She likes coffee''). La forma del verbo es casi siempre la misma — solo cambia con he/she/it."}, {"type": "explanation", "title": "LA REGLA DE LA -S EN TERCERA PERSONA", "text": "Con I, you, we, they el verbo queda en su forma base: ''I work'', ''They live''. Con he, she, it se añade -S al final: ''He works'', ''She lives''. Si el verbo termina en -s, -sh, -ch, -x, -o se añade -ES: ''He watches'', ''She goes''. Si termina en consonante + Y, la Y cambia a -IES: ''study'' → ''studies''. El verbo HAVE es irregular: ''he/she/it HAS'' (no ''haves'')."}, {"type": "table", "title": "CONJUGACIÓN DEL PRESENTE SIMPLE (verbo ''to work'')", "headers": ["Sujeto", "Forma", "Ejemplo"], "rows": [["I / You / We / They", "work (base)", "I work in a school."], ["He / She / It", "works (+s)", "She works in a school."], ["he/she + verbo en -ch/-sh/-o", "+es", "He watches TV. She goes home."], ["he/she + consonante+y", "y → ies", "He studies English."], ["he/she + have", "has (irregular)", "She has two cats."]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "I live in Bogotá. My brother lives in Quito.", "es": "Yo vivo en Bogotá. Mi hermano vive en Quito."}, {"en": "We study every night. She studies in the morning.", "es": "Nosotros estudiamos cada noche. Ella estudia en la mañana."}, {"en": "He has a new car.", "es": "Él tiene un auto nuevo."}]}, {"type": "note", "variant": "warning", "text": "El error más común de hispanohablantes es olvidar la -S con he/she/it: decir ''He work'' en vez de ''He works''. Revisa siempre el sujeto antes de escribir el verbo."}]}'::jsonb, true);

INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0013-0002-0001-000000000001', '00000002-0000-0000-0013-000000000002', 1, 'flashcard', '{"text": "work / works", "subtext": "Presente Simple: yo trabajo / él trabaja"}'::jsonb, '{"text": "trabajar", "phonetic": "/wɜːrk/"}'::jsonb, NULL, NULL),
('00000003-0013-0002-0002-000000000001', '00000002-0000-0000-0013-000000000002', 2, 'multiple_choice', '{"text": "She ___ (work) in a hospital."}'::jsonb, '{"text": "works"}'::jsonb, '["work", "working", "worked"]'::jsonb, '{"es": "Con ''she'' el verbo necesita -S: ''works''."}'::jsonb),
('00000003-0013-0002-0003-000000000001', '00000002-0000-0000-0013-000000000002', 3, 'multiple_choice', '{"text": "I ___ (live) in Bogotá."}'::jsonb, '{"text": "live"}'::jsonb, '["lives", "living", "lived"]'::jsonb, '{"es": "Con ''I'' el verbo queda en forma base: ''live'', sin -S."}'::jsonb),
('00000003-0013-0002-0004-000000000001', '00000002-0000-0000-0013-000000000002', 4, 'fill_blank', '{"text": "He ___ (study) English every day."}'::jsonb, '{"text": "studies", "accepted": ["studies"]}'::jsonb, NULL, '{"es": "''Study'' termina en consonante + Y, así que la Y cambia a -IES: ''studies''."}'::jsonb),
('00000003-0013-0002-0005-000000000001', '00000002-0000-0000-0013-000000000002', 5, 'fill_blank', '{"text": "They ___ (go) to school by bus."}'::jsonb, '{"text": "go", "accepted": ["go"]}'::jsonb, NULL, NULL),
('00000003-0013-0002-0006-000000000001', '00000002-0000-0000-0013-000000000002', 6, 'multiple_choice', '{"text": "¿Cuál oración es correcta?"}'::jsonb, '{"text": "She has a car."}'::jsonb, '["She haves a car.", "She have a car.", "She having a car."]'::jsonb, '{"es": "''Have'' es irregular: con he/she/it se convierte en ''has'', no ''haves''."}'::jsonb),
('00000003-0013-0002-0007-000000000001', '00000002-0000-0000-0013-000000000002', 7, 'translation', '{"text": "Mi hermano trabaja en un banco."}'::jsonb, '{"text": "My brother works in a bank.", "accepted": ["My brother works in a bank."]}'::jsonb, NULL, NULL),
('00000003-0013-0002-0008-000000000001', '00000002-0000-0000-0013-000000000002', 8, 'translation', '{"text": "Nosotros vivimos en México."}'::jsonb, '{"text": "We live in Mexico.", "accepted": ["We live in Mexico."]}'::jsonb, NULL, NULL);

-- ===========================================================================
-- Lesson 13.3 — El Presente Simple: Negativo e Interrogativo (do/does)
-- ===========================================================================

INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0013-000000000003', '00000001-0000-0000-0000-000000000013', '00000000-0000-0000-0001-000000000001', 3, 'presente-simple-negativo-interrogativo', '{"es": "El Presente Simple: Negativo e Interrogativo", "en": "Present Simple: Negative and Interrogative"}'::jsonb, '{"es": "Aprende a usar do/does para negar y preguntar en Presente Simple.", "en": "Learn to use do/does to make negatives and questions in Present Simple."}'::jsonb, 'grammar', 20, 15, '{"intro": "Para hacer una pregunta o una negación en Presente Simple (con verbos que no sean ''to be''), el inglés necesita un verbo auxiliar: DO o DOES. Este auxiliar no se traduce — es una pieza puramente gramatical que el español no tiene, y por eso suele confundir a los hispanohablantes.", "sections": [{"type": "explanation", "title": "LA FORMA NEGATIVA: DON''T / DOESN''T", "text": "Con I, you, we, they usamos DON''T + verbo base: ''I don''t like coffee''. Con he, she, it usamos DOESN''T + verbo base: ''She doesn''t like coffee''. Importante: cuando usas don''t/doesn''t, el verbo principal NUNCA lleva -S — el auxiliar ya muestra la persona. Es un error común decir ''She doesn''t likes'' — es incorrecto, debe ser ''She doesn''t like''."}, {"type": "explanation", "title": "LA FORMA INTERROGATIVA: DO / DOES", "text": "Para preguntar, el auxiliar va al PRINCIPIO de la oración, antes del sujeto: ''Do you like coffee?'' / ''Does she like coffee?''. Igual que en negativo, el verbo principal queda en forma base, sin -S: ''Does he work?'' (NO ''Does he works?'')."}, {"type": "table", "title": "AFIRMATIVO vs NEGATIVO vs INTERROGATIVO", "headers": ["Tipo", "I/you/we/they", "He/she/it"], "rows": [["Afirmativo", "I like tea", "She likes tea"], ["Negativo", "I don''t like tea", "She doesn''t like tea"], ["Interrogativo", "Do you like tea?", "Does she like tea?"], ["Respuesta corta (sí)", "Yes, I do.", "Yes, she does."], ["Respuesta corta (no)", "No, I don''t.", "No, she doesn''t."]]}, {"type": "examples", "title": "MINI DIÁLOGO", "items": [{"label": "Pregunta", "en": "Do you like coffee?", "es": "¿Te gusta el café?"}, {"label": "Respuesta", "en": "Yes, I do. But I don''t like tea.", "es": "Sí, me gusta. Pero no me gusta el té."}, {"label": "Tercera persona", "en": "Does your sister speak English? — No, she doesn''t.", "es": "¿Tu hermana habla inglés? — No, no habla."}]}, {"type": "note", "variant": "warning", "text": "No confundas esto con ''to be''. Con to be NUNCA se usa do/does: ''Is she happy?'' (no ''Does she is happy?''). Do/does solo aparece con verbos de acción como like, work, live, study."}]}'::jsonb, true);

INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0013-0003-0001-000000000001', '00000002-0000-0000-0013-000000000003', 1, 'fill_blank', '{"text": "I ___ (not like) spicy food."}'::jsonb, '{"text": "don''t like", "accepted": ["don''t like", "do not like"]}'::jsonb, NULL, NULL),
('00000003-0013-0003-0002-000000000001', '00000002-0000-0000-0013-000000000003', 2, 'fill_blank', '{"text": "She ___ (not work) on Sundays."}'::jsonb, '{"text": "doesn''t work", "accepted": ["doesn''t work", "does not work"]}'::jsonb, NULL, '{"es": "Con she/he/it usamos ''doesn''t'' + verbo base (sin -S)."}'::jsonb),
('00000003-0013-0003-0003-000000000001', '00000002-0000-0000-0013-000000000003', 3, 'multiple_choice', '{"text": "¿Cuál es la pregunta correcta?"}'::jsonb, '{"text": "Does he speak English?"}'::jsonb, '["Does he speaks English?", "Is he speak English?", "Do he speak English?"]'::jsonb, '{"es": "Con ''he'' el auxiliar es ''does'' y el verbo principal queda en forma base: ''speak'', no ''speaks''."}'::jsonb),
('00000003-0013-0003-0004-000000000001', '00000002-0000-0000-0013-000000000003', 4, 'multiple_choice', '{"text": "¿Cuál es la respuesta corta correcta a ''Do you have a car?'' (no)?"}'::jsonb, '{"text": "No, I don''t."}'::jsonb, '["No, I not.", "No, I doesn''t.", "No, not."]'::jsonb, '{"es": "La respuesta corta repite el auxiliar de la pregunta: ''do'' → ''No, I don''t.''"}'::jsonb),
('00000003-0013-0003-0005-000000000001', '00000002-0000-0000-0013-000000000003', 5, 'fill_blank', '{"text": "___ they live in Canada? (pregunta)"}'::jsonb, '{"text": "Do", "accepted": ["Do"]}'::jsonb, NULL, NULL),
('00000003-0013-0003-0006-000000000001', '00000002-0000-0000-0013-000000000003', 6, 'fill_blank', '{"text": "___ she speak French? (pregunta, tercera persona)"}'::jsonb, '{"text": "Does", "accepted": ["Does"]}'::jsonb, NULL, NULL),
('00000003-0013-0003-0007-000000000001', '00000002-0000-0000-0013-000000000003', 7, 'translation', '{"text": "Yo no trabajo los fines de semana."}'::jsonb, '{"text": "I don''t work on weekends.", "accepted": ["I don''t work on weekends.", "I do not work on weekends."]}'::jsonb, NULL, NULL),
('00000003-0013-0003-0008-000000000001', '00000002-0000-0000-0013-000000000003', 8, 'translation', '{"text": "¿Hablas español? Sí, hablo."}'::jsonb, '{"text": "Do you speak Spanish? Yes, I do.", "accepted": ["Do you speak Spanish? Yes, I do."]}'::jsonb, NULL, NULL);

-- ===========================================================================
-- Lesson 13.4 — There Is / There Are
-- ===========================================================================

INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0013-000000000004', '00000001-0000-0000-0000-000000000013', '00000000-0000-0000-0001-000000000001', 4, 'there-is-there-are', '{"es": "There Is / There Are", "en": "There Is / There Are"}'::jsonb, '{"es": "Aprende a decir que algo existe o hay algo en un lugar, usando there is y there are.", "en": "Learn to say that something exists or is present somewhere, using there is and there are."}'::jsonb, 'grammar', 20, 15, '{"intro": "''There is'' y ''there are'' se usan para decir que algo EXISTE en un lugar — equivalen al ''hay'' del español. La elección entre IS y ARE depende de si lo que sigue es singular/incontable o plural, no de quién habla.", "sections": [{"type": "explanation", "title": "THERE IS (singular / incontable)", "text": "Usamos ''there is'' (contracción: ''there''s'') cuando lo que sigue es UNA cosa o algo incontable: ''There is a book on the table.'' / ''There''s some water in the bottle.''"}, {"type": "explanation", "title": "THERE ARE (plural)", "text": "Usamos ''there are'' cuando lo que sigue es plural (dos o más cosas): ''There are three books on the table.'' No existe contracción corta para ''there are''."}, {"type": "table", "title": "AFIRMATIVO, NEGATIVO E INTERROGATIVO", "headers": ["Tipo", "Singular/incontable", "Plural"], "rows": [["Afirmativo", "There is a cat.", "There are two cats."], ["Negativo", "There isn''t a cat.", "There aren''t any cats."], ["Interrogativo", "Is there a cat?", "Are there any cats?"]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "There''s a pharmacy near here.", "es": "Hay una farmacia cerca de aquí."}, {"en": "There are many people at the party.", "es": "Hay mucha gente en la fiesta."}, {"en": "There isn''t any milk in the fridge.", "es": "No hay leche en el refrigerador."}, {"en": "Is there a problem?", "es": "¿Hay algún problema?"}]}, {"type": "note", "variant": "warning", "text": "No confundas ''there is/are'' (hay) con ''it is'' (es/está). ''There is a book'' = hay un libro (existencia). ''It is a book'' = es un libro (identificación). Son estructuras distintas aunque ambas usen ''to be''."}]}'::jsonb, true);

INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0013-0004-0001-000000000001', '00000002-0000-0000-0013-000000000004', 1, 'flashcard', '{"text": "There is", "subtext": "Existencia, singular"}'::jsonb, '{"text": "hay (uno/a)", "phonetic": "/ðɛər ɪz/"}'::jsonb, NULL, NULL),
('00000003-0013-0004-0002-000000000001', '00000002-0000-0000-0013-000000000004', 2, 'flashcard', '{"text": "There are", "subtext": "Existencia, plural"}'::jsonb, '{"text": "hay (varios/as)", "phonetic": "/ðɛər ɑːr/"}'::jsonb, NULL, NULL),
('00000003-0013-0004-0003-000000000001', '00000002-0000-0000-0013-000000000004', 3, 'multiple_choice', '{"text": "¿Cuál oración es correcta?"}'::jsonb, '{"text": "There are three books on the table."}'::jsonb, '["There is three books on the table.", "There are three book on the table.", "There a three books on the table."]'::jsonb, '{"es": "''Three books'' es plural, así que necesita ''there ARE'', no ''there is''."}'::jsonb),
('00000003-0013-0004-0004-000000000001', '00000002-0000-0000-0013-000000000004', 4, 'fill_blank', '{"text": "___ a cat in the garden. (singular)"}'::jsonb, '{"text": "There is", "accepted": ["There is", "There''s"]}'::jsonb, NULL, NULL),
('00000003-0013-0004-0005-000000000001', '00000002-0000-0000-0013-000000000004', 5, 'fill_blank', '{"text": "___ many people at the party. (plural)"}'::jsonb, '{"text": "There are", "accepted": ["There are"]}'::jsonb, NULL, NULL),
('00000003-0013-0004-0006-000000000001', '00000002-0000-0000-0013-000000000004', 6, 'multiple_choice', '{"text": "¿Cómo preguntas ''¿Hay una farmacia cerca de aquí?''?"}'::jsonb, '{"text": "Is there a pharmacy near here?"}'::jsonb, '["There is a pharmacy near here?", "Is a pharmacy there near here?", "There a pharmacy is near here?"]'::jsonb, '{"es": "En la pregunta, ''is'' se mueve antes de ''there'': ''Is there...?''"}'::jsonb),
('00000003-0013-0004-0007-000000000001', '00000002-0000-0000-0013-000000000004', 7, 'translation', '{"text": "Hay un libro en la mesa."}'::jsonb, '{"text": "There is a book on the table.", "accepted": ["There is a book on the table.", "There''s a book on the table."]}'::jsonb, NULL, NULL),
('00000003-0013-0004-0008-000000000001', '00000002-0000-0000-0013-000000000004', 8, 'translation', '{"text": "No hay leche en el refrigerador."}'::jsonb, '{"text": "There isn''t any milk in the fridge.", "accepted": ["There isn''t any milk in the fridge.", "There is no milk in the fridge."]}'::jsonb, NULL, NULL);

-- ===========================================================================
-- Lesson 13.5 — Imperativos y el Verbo Can (habilidad)
-- ===========================================================================

INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0013-000000000005', '00000001-0000-0000-0000-000000000013', '00000000-0000-0000-0001-000000000001', 5, 'imperativos-y-can', '{"es": "Imperativos y el Verbo Can", "en": "Imperatives and the Verb Can"}'::jsonb, '{"es": "Aprende a dar instrucciones con imperativos y a hablar de habilidades con can/can''t.", "en": "Learn to give instructions with imperatives and talk about abilities with can/can''t."}'::jsonb, 'grammar', 20, 15, '{"intro": "En esta lección aprenderás dos estructuras cortas pero muy usadas: el imperativo, para dar instrucciones u órdenes directas, y el verbo modal ''can'', para hablar de lo que alguien sabe o puede hacer. Ya usaste ''can'' para pedir cosas cortésmente (''Can I have...?''); ahora verás su otro uso: la habilidad.", "sections": [{"type": "explanation", "title": "LOS IMPERATIVOS", "text": "El imperativo se forma con el verbo en su forma BASE, sin sujeto: ''Open the door.'' (Abre la puerta.) ''Listen carefully.'' (Escucha con atención.) Para pedir algo con más cortesía, añade ''please'' al final o al principio: ''Close the window, please.'' Para el imperativo NEGATIVO, usa ''Don''t'' + verbo base: ''Don''t worry.'' (No te preocupes.) ''Don''t talk, please.'' (No hables, por favor.)"}, {"type": "explanation", "title": "CAN PARA HABILIDAD", "text": "''Can'' + verbo base expresa que alguien SABE o PUEDE hacer algo: ''I can swim.'' (Sé nadar.) La forma negativa es ''can''t'' (o ''cannot''): ''She can''t drive.'' (Ella no sabe manejar.) ''Can'' no cambia de forma según el sujeto — es igual para I, you, he, she, it, we, they. Para preguntar, ''can'' va al principio: ''Can you swim?''"}, {"type": "table", "title": "IMPERATIVOS Y CAN — EJEMPLOS", "headers": ["Estructura", "Ejemplo", "Español"], "rows": [["Imperativo afirmativo", "Open the door.", "Abre la puerta."], ["Imperativo + please", "Sit down, please.", "Siéntate, por favor."], ["Imperativo negativo", "Don''t worry.", "No te preocupes."], ["Can (habilidad)", "I can speak two languages.", "Sé hablar dos idiomas."], ["Can''t (habilidad negativa)", "He can''t drive.", "Él no sabe manejar."], ["Can (pregunta)", "Can you swim?", "¿Sabes nadar?"]]}, {"type": "examples", "title": "EJEMPLOS EN CONTEXTO", "items": [{"label": "Instrucciones de clase", "en": "Open your books. Don''t talk, please. Listen to the audio.", "es": "Abran sus libros. No hablen, por favor. Escuchen el audio."}, {"label": "Habilidad", "en": "I can cook, but I can''t bake. Can you bake?", "es": "Sé cocinar, pero no sé hornear. ¿Sabes hornear?"}]}, {"type": "note", "variant": "tip", "text": "Ya conoces ''Can I have...?'' como frase de cortesía para pedir algo — ese es un uso distinto de ''can'' (petición), no de habilidad. Misma palabra, dos funciones: pedir algo cortésmente, o decir lo que alguien sabe hacer."}]}'::jsonb, true);

