('00000003-0013-0005-0003-000000000001', '00000002-0000-0000-0013-000000000005', 3, 'multiple_choice', '{"text": "¿Cuál es un imperativo correcto?"}'::jsonb, '{"text": "Close the window, please."}'::jsonb, '["You close the window.", "Closing the window.", "Closed the window."]'::jsonb, '{"es": "El imperativo usa el verbo en forma base, sin sujeto: ''Close...'', no ''You close...''."}'::jsonb),
('00000003-0013-0005-0004-000000000001', '00000002-0000-0000-0013-000000000005', 4, 'fill_blank', '{"text": "___ talking, please! (imperativo negativo: no hables)"}'::jsonb, '{"text": "Don''t", "accepted": ["Don''t", "Do not"]}'::jsonb, NULL, NULL),
('00000003-0013-0005-0005-000000000001', '00000002-0000-0000-0013-000000000005', 5, 'fill_blank', '{"text": "I ___ speak three languages. (habilidad)"}'::jsonb, '{"text": "can", "accepted": ["can"]}'::jsonb, NULL, NULL),
('00000003-0013-0005-0006-000000000001', '00000002-0000-0000-0013-000000000005', 6, 'multiple_choice', '{"text": "¿Cómo preguntas si alguien sabe nadar?"}'::jsonb, '{"text": "Can you swim?"}'::jsonb, '["Do you can swim?", "Are you can swim?", "You can swim?"]'::jsonb, '{"es": "''Can'' va directamente al principio de la pregunta, sin auxiliar adicional."}'::jsonb),
('00000003-0013-0005-0007-000000000001', '00000002-0000-0000-0013-000000000005', 7, 'translation', '{"text": "Ella no puede manejar."}'::jsonb, '{"text": "She can''t drive.", "accepted": ["She can''t drive.", "She cannot drive."]}'::jsonb, NULL, NULL),
('00000003-0013-0005-0008-000000000001', '00000002-0000-0000-0013-000000000005', 8, 'translation', '{"text": "Por favor, abre la ventana."}'::jsonb, '{"text": "Open the window, please.", "accepted": ["Open the window, please.", "Please, open the window."]}'::jsonb, NULL, NULL);
